const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const section=document.createElement('section');section.className='composer research-workspace pack-workspace';section.id='pack-workspace';
section.innerHTML=`<div class="composer-top"><div><div class="eyebrow">THE OPPORTUNITY LIBRARY</div><h2>Explore what’s possible.</h2><p>Research, founders, social impact and learning. Sources attached.</p></div><span class="small-tag">7 CONNECTED CLUSTERS</span></div><div id="pack-clusters" class="pack-clusters"></div><form id="pack-query-form"><label for="pack-query">Ask across the library · English or Hindi</label><textarea id="pack-query" rows="2" placeholder="Find startup funding announcements in 2026" minlength="3" maxlength="2000" required></textarea><button class="primary">Search collected records ↗</button><button type="button" class="secondary" id="pack-reload">Reload library</button></form><div id="pack-status" role="status"></div><div id="pack-output"></div>`;
document.querySelector('.hero').after(section);
let plan={category:'all',filters:[]},current=null,view='records';
async function api(path,body){const r=await fetch(path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:undefined);const j=await r.json();if(!r.ok)throw Error(r.status===404?'The opportunity library needs the latest backend deployment. Catalogue search remains available.':j.error||'Request failed');return j}
const status=s=>document.querySelector('#pack-status').textContent=s;
async function clusters(){const o=await api('/api/packs');document.querySelector('#pack-clusters').innerHTML=o.clusters.map(c=>`<button class="pack-cluster ${plan.category===c.id?'selected':''}" data-cluster="${esc(c.id)}"><span>${esc(c.title)}</span><strong>${c.records}</strong><small>${c.sources} sources · ${c.failures} gaps</small><small>${c.last_checked?'Checked '+new Date(c.last_checked).toLocaleDateString():'Not collected yet'}</small></button>`).join('');document.querySelectorAll('[data-cluster]').forEach(b=>b.onclick=async()=>{plan={category:b.dataset.cluster,filters:[]};await load();await clusters()})}
function evidence(r){const d=document.querySelector('#pack-evidence');d.innerHTML=`<div class="composer-top"><h3>${esc(r.name)}</h3><button class="secondary" id="pack-close-evidence">Close</button></div><p>${esc(r.review_status)} · ${esc(r.freshness)} · identity kept separate across sources</p><blockquote>${esc(r.identity_quote)}</blockquote>${r.evidence.map(e=>`<article class="source-card"><strong>${esc(e.field.replaceAll('_',' '))}: ${esc(e.value)}</strong><p>${esc(e.subject_binding||'named_subject')} · text offset ${e.offset}</p><blockquote>${esc(e.quote)}</blockquote></article>`).join('')}<a href="${esc(r.source_url)}" target="_blank" rel="noreferrer">Open original source ↗</a><p>Retrieved ${esc(r.checked_at)} · commercial reuse ${esc(r.commercial_reuse)}</p>`;document.querySelector('#pack-close-evidence').onclick=()=>d.innerHTML='';d.scrollIntoView({behavior:'smooth',block:'nearest'})}
function graph(rows){const picked=rows.slice(0,30);return `<p>Showing ${picked.length} of ${rows.length} records. Solid links mean “sourced from”. Dashed relationship claims remain unreviewed.</p><div class="pack-graph">${picked.map(r=>`<div class="pack-graph-row"><button class="graph-node entity-node" data-pack-record="${r.id}"><small>${esc(r.kind.replaceAll('_',' '))}</small><strong>${esc(r.name)}</strong><span>Inspect evidence ↗</span></button><div class="graph-connector"><span>sourced from</span><i>→</i></div><a class="graph-node source-node" href="${esc(r.source_url)}" target="_blank" rel="noreferrer"><small>PRIMARY SOURCE</small><strong>${esc(new URL(r.source_url).hostname)}</strong><span>${esc(r.category)} · ${esc(r.freshness)}</span></a></div>${r.relationships.map(e=>`<div class="pack-graph-row relationship-row"><div class="graph-node">${esc(r.name)}</div><div class="graph-connector"><span>${esc(e.predicate.replaceAll('_',' '))}</span><i>⇢</i><small>Unreviewed claim</small></div><button class="graph-node" data-pack-record="${r.id}">${esc(e.target)}<span>Inspect quote ↗</span></button></div>`).join('')}`).join('')}</div>`}
function render(result){current=result;const rows=result.records;const url='/api/packs/records?'+new URLSearchParams({plan:JSON.stringify(plan),export:'csv'});const fields=['organisation','location','eligibility','deadline','announcement_date','amount','round'];
 document.querySelector('#pack-output').innerHTML=`<div class="research-metrics"><span>${rows.length} collected records</span><span>${result.counts.matched_fields} match supported fields</span><span>${result.counts.needs_review} need review</span><span>${result.counts.excluded} outside filters</span></div>${plan.unsupported?.length?`<p class="research-note">Unsupported requirements: ${esc(plan.unsupported.join('; '))}</p>`:''}<details><summary>Inspect interpreted conditions</summary><pre>${esc(JSON.stringify(plan,null,2))}</pre></details><div class="research-actions"><button class="secondary" id="pack-records">Records</button><button class="secondary" id="pack-graph">Knowledge graph</button><a class="dark-button" href="${esc(url)}">↓ Research CSV + evidence</a>${plan.category!=='all'?'<button class="secondary" id="pack-refresh">Refresh sources</button>':''}</div><p>Research export includes all shown candidates and their match status. Commercial packs are unavailable until source reuse permission is documented.</p><div id="pack-evidence" aria-live="polite"></div>${view==='graph'?graph(rows):`<div class="table-scroll"><table><thead><tr><th>Name / type</th><th>Check status</th>${fields.map(f=>`<th>${esc(f.replaceAll('_',' '))}</th>`).join('')}<th>Evidence</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>${esc(r.kind.replaceAll('_',' '))}</small></td><td><span class="pill">${esc(r.match_status.replaceAll('_',' '))}</span><small>${esc(r.freshness)}</small><small>${esc(r.deadline_status.replaceAll('_',' '))}</small></td>${fields.map(f=>`<td>${r.attributes[f]?esc(r.attributes[f].join(' / ')):'<span class="missing-value">Not provided by source</span>'}</td>`).join('')}<td><button class="secondary" data-pack-record="${r.id}">Inspect claims ↗</button></td></tr>`).join('')}</tbody></table></div>`}`;
 document.querySelector('#pack-records').onclick=()=>{view='records';render(current)};document.querySelector('#pack-graph').onclick=()=>{view='graph';render(current)};
 document.querySelectorAll('[data-pack-record]').forEach(b=>b.onclick=()=>evidence(rows.find(r=>r.id===b.dataset.packRecord)));
 const refresh=document.querySelector('#pack-refresh');if(refresh)refresh.onclick=async()=>{try{refresh.disabled=true;const r=await api('/api/packs/refresh',{category:plan.category});status(r.note)}catch(e){status(e.message)}finally{refresh.disabled=false}};
}
async function load(){try{const r=await api('/api/packs/records?'+new URLSearchParams({plan:JSON.stringify(plan)}));render(r)}catch(e){status(e.message)}}
document.querySelector('#pack-query-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;status('Interpreting conditions, then checking collected evidence…');try{const r=await api('/api/packs/query',{query:document.querySelector('#pack-query').value});plan=r.plan;render(r);await clusters();status('Search complete. Review the interpreted conditions and source evidence.')}catch(e){status(e.message)}finally{b.disabled=false}};
document.querySelector('#pack-reload').onclick=()=>Promise.all([clusters(),load()]).catch(e=>status(e.message));
clusters().then(load).catch(e=>status(e.message));
